const API = require("../../utils/api");Page({data:{roomId:"",roomCharge:0,scanTotal:0,pendingPayment:0,orders:[]},onLoad(e){const roomId=e.room_id||"";this.setData({roomId});API.getScanBill(roomId).then(b=>{this.setData({roomCharge:b.billSummary.roomCharge,scanTotal:b.billSummary.scanTotal,pendingPayment:b.billSummary.pendingPayment,orders:b.scanOrders})})},cancel(e){const id=e.currentTarget.dataset.id;wx.showModal({title:"确认撤销",content:"确定撤销此订单?",success:r=>{if(r.confirm)API.cancelScanOrder(id).then(()=>{wx.showToast({title:"已撤销",icon:"success"});API.getScanBill(this.data.roomId).then(b=>this.setData({orders:b.scanOrders}))})}})},settle(){API.settleScanBill(this.data.roomId,{paymentMethod:"WxPay"}).then(r=>{wx.showToast({title:"结算成功 ¥"+r.totalAmount.toFixed(2),icon:"none"});API.getScanBill(this.data.roomId).then(b=>this.setData({orders:b.scanOrders,pendingPayment:b.billSummary.pendingPayment}))})}})